package edu.brook;

/**
 * Cooperate Defect Style Java Implementation.
 * 
 * Generated by metaabm system: Jul 28, 2009 2:17:09 PM PDT in project: org.eclipse.amp.amf.examples.ascape  */

public class CooperateDefectStyle extends org.ascape.util.vis.DrawFeature {

	public void draw(java.awt.Graphics g, Object object, int width, int height) {
		java.awt.Shape shape = null;
		org.ascape.model.HostCell rootActGroupCell = (org.ascape.model.HostCell) object;
		if (rootActGroupCell.getOccupant() instanceof Player) {
			Player rootActGroup = (Player) rootActGroupCell.getOccupant();
			Player playerRule = rootActGroup;

			if (playerRule.isCooperate()) {

				java.awt.Color playerRuleColorBlue = java.awt.Color.BLUE

				;

				g.setColor(playerRuleColorBlue);
				shape = new java.awt.geom.Ellipse2D.Double(0, 0, width - 2,
						height - 2);
				((java.awt.Graphics2D) g).fill(shape);

			}

			if (!(playerRule.isCooperate())) {

				java.awt.Color playerRuleColorRed = java.awt.Color.RED

				;

				g.setColor(playerRuleColorRed);
				shape = new java.awt.geom.Ellipse2D.Double(0, 0, width - 2,
						height - 2);
				((java.awt.Graphics2D) g).fill(shape);

			}

		}
	}
}
